Lemma hwb_after_ext : forall b f g,
  (forall key, f key = g key) -> hwb_after b f = hwb_after b g.
Proof.
  intros b f g H. unfold hwb_after.
  rewrite (H "pc"). rewrite (H "mu"). rewrite (H "err"). rewrite (H "halted"). rewrite (H "regs"). rewrite (H "mem"). rewrite (H "imem"). rewrite (H "partition_ops"). rewrite (H "mdl_ops"). rewrite (H "info_gain"). rewrite (H "error_code"). rewrite (H "logic_acc"). rewrite (H "cert_addr"). rewrite (H "active_module"). rewrite (H "mstatus"). rewrite (H "mcycle_lo"). rewrite (H "mcycle_hi"). rewrite (H "minstret_lo"). rewrite (H "minstret_hi"). rewrite (H "trap_vector"). rewrite (H "certified"). rewrite (H "lassert_phase"). rewrite (H "lassert_kind"). rewrite (H "lassert_fbase"). rewrite (H "lassert_cbase"). rewrite (H "lassert_flen"). rewrite (H "lassert_clen"). rewrite (H "lassert_nvars"). rewrite (H "lassert_fptr"). rewrite (H "lassert_cptr"). rewrite (H "lassert_fbuf"). rewrite (H "lassert_cbuf"). rewrite (H "lassert_clause_sat"). rewrite (H "lassert_counter_clause_sat"). rewrite (H "lassert_counter_seen_fail"). rewrite (H "chsh_phase"). rewrite (H "chsh_n00"). rewrite (H "chsh_n01"). rewrite (H "chsh_n10"). rewrite (H "chsh_n11"). rewrite (H "chsh_d00"). rewrite (H "chsh_d01"). rewrite (H "chsh_d10"). rewrite (H "chsh_d11"). rewrite (H "chsh_sign00"). rewrite (H "chsh_sign01"). rewrite (H "chsh_sign10"). rewrite (H "chsh_sign11"). rewrite (H "chsh_n00sq"). rewrite (H "chsh_n01sq"). rewrite (H "chsh_n10sq"). rewrite (H "chsh_n11sq"). rewrite (H "chsh_d00sq"). rewrite (H "chsh_d01sq"). rewrite (H "chsh_d10sq"). rewrite (H "chsh_d11sq"). rewrite (H "chsh_A_pos"). rewrite (H "chsh_A_neg_a"). rewrite (H "chsh_A_neg_b"). rewrite (H "chsh_B_pos"). rewrite (H "chsh_B_neg_a"). rewrite (H "chsh_B_neg_b"). rewrite (H "chsh_d00d01"). rewrite (H "chsh_n10n11"). rewrite (H "chsh_d10d11"). rewrite (H "chsh_n00n01"). rewrite (H "chsh_abs_C1"). rewrite (H "chsh_abs_C2"). rewrite (H "chsh_C_sq"). rewrite (H "chsh_A_times_B"). rewrite (H "chsh_check_result"). rewrite (H "bus_load_instr_addr"). rewrite (H "bus_load_instr_data"). rewrite (H "bus_load_instr_kick"). rewrite (H "mu_tensor"). rewrite (H "module_tensors"). rewrite (H "csr_status"). rewrite (H "csr_heap_base"). rewrite (H "ptTable"). rewrite (H "pt_next_id"). rewrite (H "morph_src_table"). rewrite (H "morph_dst_table"). rewrite (H "morph_coupling_desc_table"). rewrite (H "morph_valid_table"). rewrite (H "morph_identity_table"). rewrite (H "morph_next_id"). rewrite (H "coupling_desc_base_table"). rewrite (H "coupling_desc_count_table"). rewrite (H "coupling_desc_valid_table"). rewrite (H "coupling_desc_label_table"). rewrite (H "coupling_desc_label_len_table"). rewrite (H "coupling_desc_next_id"). rewrite (H "coupling_pair_src_table"). rewrite (H "coupling_pair_dst_table"). rewrite (H "coupling_pair_valid_table"). rewrite (H "coupling_pair_next_id"). rewrite (H "mc_phase"). rewrite (H "mc_op"). rewrite (H "mc_mem_base"). rewrite (H "mc_pair_count"). rewrite (H "mc_read_ptr"). rewrite (H "mc_src1_base"). rewrite (H "mc_src1_count"). rewrite (H "mc_src2_base"). rewrite (H "mc_src2_count"). rewrite (H "mc_i"). rewrite (H "mc_j"). rewrite (H "mc_is_id1"). rewrite (H "mc_is_id2"). rewrite (H "mc_write_base"). rewrite (H "mc_write_ptr"). rewrite (H "mc_norm_ptr"). rewrite (H "mc_duplicate"). rewrite (H "mc_dst_reg"). rewrite (H "mc_morph_slot"). rewrite (H "mc_new_src_mod"). rewrite (H "mc_new_dst_mod"). rewrite (H "mc_cost"). rewrite (H "formula_desc_base_table"). rewrite (H "formula_desc_count_table"). rewrite (H "formula_desc_valid_table"). rewrite (H "formula_desc_next_id"). rewrite (H "cert_desc_base_table"). rewrite (H "cert_desc_count_table"). rewrite (H "cert_desc_valid_table"). rewrite (H "cert_desc_next_id"). rewrite (H "desc_meta_subtype_table"). rewrite (H "desc_meta_kind_table"). rewrite (H "desc_meta_inline_len_table"). rewrite (H "desc_meta_aux_table"). rewrite (H "desc_meta_valid_table"). rewrite (H "desc_meta_next_id"). rewrite (H "wc_same_00"). rewrite (H "wc_diff_00"). rewrite (H "wc_same_01"). rewrite (H "wc_diff_01"). rewrite (H "wc_same_10"). rewrite (H "wc_diff_10"). rewrite (H "wc_same_11"). rewrite (H "wc_diff_11").
  reflexivity.
Qed.

